-- POS single-terminal schema (PostgreSQL 15+)
-- Conventions: uuid PKs (UUIDv7 generated by the app), money = bigint minor units,
-- quantities = numeric(12,3), timestamps = timestamptz (UTC), enums = text + CHECK.

-- ============ Settings & licensing ============
CREATE TABLE app_setting (
    key         text PRIMARY KEY,
    value       jsonb       NOT NULL,
    updated_at  timestamptz NOT NULL DEFAULT now()
);

-- ============ Users & roles ============
CREATE TABLE role (
    id    uuid PRIMARY KEY,
    code  text NOT NULL UNIQUE,            -- OWNER, MANAGER, CASHIER
    name  text NOT NULL
);

CREATE TABLE role_permission (
    role_id     uuid NOT NULL REFERENCES role(id) ON DELETE CASCADE,
    permission  text NOT NULL,             -- e.g. ORDER_VOID, STOCK_ADJUST
    PRIMARY KEY (role_id, permission)
);

CREATE TABLE app_user (
    id               uuid PRIMARY KEY,
    username         text    NOT NULL UNIQUE,
    display_name     text    NOT NULL,
    pin_hash         text    NOT NULL,
    role_id          uuid    NOT NULL REFERENCES role(id),
    active           boolean NOT NULL DEFAULT true,
    failed_attempts  int     NOT NULL DEFAULT 0,
    locked_until     timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);

-- ============ Catalog ============
CREATE TABLE tax_rate (
    id         uuid PRIMARY KEY,
    name       text    NOT NULL,
    rate_bp    int     NOT NULL CHECK (rate_bp >= 0 AND rate_bp <= 10000),  -- basis points: 1500 = 15%
    inclusive  boolean NOT NULL DEFAULT true,                                -- price includes tax
    active     boolean NOT NULL DEFAULT true
);

CREATE TABLE category (
    id          uuid PRIMARY KEY,
    name        text    NOT NULL UNIQUE,
    sort_order  int     NOT NULL DEFAULT 0,
    active      boolean NOT NULL DEFAULT true
);

CREATE TABLE product (
    id             uuid PRIMARY KEY,
    category_id    uuid    NOT NULL REFERENCES category(id),
    name           text    NOT NULL,
    item_class     text    NOT NULL DEFAULT 'MERCHANDISE' CHECK (item_class IN ('MERCHANDISE','NON_MERCHANDISE')),
    non_merch_type text    CHECK (non_merch_type IN ('SERVICE_CHARGE','DELIVERY','TIP','DEPOSIT','GIFT_CARD','OTHER')),
    sku            text    UNIQUE,
    barcode        text    UNIQUE,
    price_minor    bigint  NOT NULL CHECK (price_minor >= 0),
    tax_rate_id    uuid    REFERENCES tax_rate(id),
    kitchen_print  boolean NOT NULL DEFAULT false,   -- include on kitchen ticket
    track_stock    boolean NOT NULL DEFAULT false,
    sort_order     int     NOT NULL DEFAULT 0,
    active         boolean NOT NULL DEFAULT true,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    CHECK ((item_class = 'NON_MERCHANDISE') = (non_merch_type IS NOT NULL)),
    CHECK (item_class = 'MERCHANDISE' OR NOT track_stock)      -- only merchandise has stock
);
CREATE INDEX ix_product_category ON product(category_id) WHERE active;

CREATE TABLE modifier_group (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    min_select  int  NOT NULL DEFAULT 0,
    max_select  int  NOT NULL DEFAULT 1,
    CHECK (min_select >= 0 AND max_select >= min_select)
);

CREATE TABLE modifier (
    id                uuid PRIMARY KEY,
    group_id          uuid    NOT NULL REFERENCES modifier_group(id) ON DELETE CASCADE,
    name              text    NOT NULL,
    price_delta_minor bigint  NOT NULL DEFAULT 0,
    sort_order        int     NOT NULL DEFAULT 0,
    active            boolean NOT NULL DEFAULT true
);

CREATE TABLE product_modifier_group (
    product_id  uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,
    group_id    uuid NOT NULL REFERENCES modifier_group(id) ON DELETE CASCADE,
    sort_order  int  NOT NULL DEFAULT 0,
    PRIMARY KEY (product_id, group_id)
);

CREATE TABLE dining_table (
    id      uuid PRIMARY KEY,
    name    text    NOT NULL UNIQUE,
    seats   int,
    active  boolean NOT NULL DEFAULT true
);

-- ============ Inventory ============
CREATE TABLE stock_item (
    id             uuid PRIMARY KEY,
    name           text    NOT NULL UNIQUE,
    unit           text    NOT NULL,                 -- pcs, kg, l ...
    reorder_level  numeric(12,3) NOT NULL DEFAULT 0,
    active         boolean NOT NULL DEFAULT true,
    created_at     timestamptz NOT NULL DEFAULT now()
);

-- Product -> stock consumption. Product-level stock = one row with qty 1.
CREATE TABLE recipe_item (
    product_id    uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,
    stock_item_id uuid NOT NULL REFERENCES stock_item(id),
    quantity      numeric(12,3) NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (product_id, stock_item_id)
);

-- ============ Day / cash ============
CREATE TABLE cash_session (
    id             uuid PRIMARY KEY,
    business_date  date    NOT NULL,
    status         text    NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')),
    opened_by      uuid    NOT NULL REFERENCES app_user(id),
    opened_at      timestamptz NOT NULL DEFAULT now(),
    opening_float  bigint  NOT NULL CHECK (opening_float >= 0),
    closed_by      uuid    REFERENCES app_user(id),
    closed_at      timestamptz,
    expected_cash  bigint,
    counted_cash   bigint,
    variance       bigint,
    z_report       jsonb,                              -- immutable snapshot at day end
    notes          text,
    CHECK ((status = 'OPEN' AND closed_at IS NULL) OR (status = 'CLOSED' AND closed_at IS NOT NULL))
);
CREATE UNIQUE INDEX ux_cash_session_one_open ON cash_session ((true)) WHERE status = 'OPEN';
CREATE UNIQUE INDEX ux_cash_session_date ON cash_session (business_date);

CREATE TABLE cash_movement (
    id               uuid PRIMARY KEY,
    cash_session_id  uuid   NOT NULL REFERENCES cash_session(id),
    type             text   NOT NULL CHECK (type IN ('PAID_IN','PAID_OUT','EXPENSE')),
    amount_minor     bigint NOT NULL CHECK (amount_minor > 0),
    reason           text   NOT NULL,
    user_id          uuid   NOT NULL REFERENCES app_user(id),
    created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_cash_movement_session ON cash_movement(cash_session_id);

-- ============ Sales: transaction -> items (sale | tender) ============
CREATE TABLE receipt_counter (
    business_date  date PRIMARY KEY,
    last_no        int  NOT NULL DEFAULT 0
);

-- One row per sale (or refund); holds identity, status, receipt number and computed totals.
-- "transaction" is reserved, hence pos_transaction.
-- All amounts are stored as positive magnitudes; REFUND transactions are signed by the *_signed views.
CREATE TABLE pos_transaction (
    id                       uuid PRIMARY KEY,
    type                     text   NOT NULL DEFAULT 'SALE' CHECK (type IN ('SALE','REFUND')),
    status                   text   NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','COMPLETED','CANCELLED')),
    cash_session_id          uuid   NOT NULL REFERENCES cash_session(id),
    business_date            date   NOT NULL,
    receipt_no               text   UNIQUE,            -- only COMPLETED transactions; gap-free per day
    order_type               text   NOT NULL CHECK (order_type IN ('DINE_IN','TAKEAWAY')),
    table_id                 uuid   REFERENCES dining_table(id),
    original_transaction_id  uuid   REFERENCES pos_transaction(id),   -- REFUND -> the SALE it reverses
    subtotal_minor           bigint NOT NULL DEFAULT 0 CHECK (subtotal_minor >= 0),
    discount_minor           bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),   -- transaction-level discount
    discount_reason          text,
    tax_minor                bigint NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
    rounding_minor           bigint NOT NULL DEFAULT 0,
    total_minor              bigint NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
    note                     text,
    created_by               uuid   NOT NULL REFERENCES app_user(id),
    created_at               timestamptz NOT NULL DEFAULT now(),
    completed_at             timestamptz,
    cancelled_by             uuid   REFERENCES app_user(id),
    cancelled_at             timestamptz,
    reason                   text,                     -- refund / cancel reason
    CHECK ((type = 'REFUND') = (original_transaction_id IS NOT NULL)),
    CHECK (type <> 'REFUND' OR reason IS NOT NULL),
    CHECK (status <> 'COMPLETED' OR (completed_at IS NOT NULL AND receipt_no IS NOT NULL)),
    CHECK ((status = 'CANCELLED') = (cancelled_at IS NOT NULL)),
    CHECK (status <> 'CANCELLED' OR (receipt_no IS NULL AND reason IS NOT NULL))
);
CREATE INDEX ix_txn_date    ON pos_transaction(business_date, status);
CREATE INDEX ix_txn_session ON pos_transaction(cash_session_id);
CREATE INDEX ix_txn_table   ON pos_transaction(table_id) WHERE status = 'OPEN';
CREATE INDEX ix_txn_orig    ON pos_transaction(original_transaction_id) WHERE original_transaction_id IS NOT NULL;

-- Base row for everything in the transaction. kind selects exactly one subtype row.
CREATE TABLE basket_item (
    id            uuid PRIMARY KEY,
    transaction_id uuid  NOT NULL REFERENCES pos_transaction(id),
    kind          text   NOT NULL CHECK (kind IN ('SALE','TENDER')),
    line_no       int    NOT NULL,
    amount_minor  bigint NOT NULL CHECK (amount_minor >= 0),   -- SALE: line total; TENDER: amount applied to the bill
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (transaction_id, line_no),
    UNIQUE (id, kind)                                           -- lets subtypes pin their kind via FK
);
CREATE INDEX ix_basket_item_txn ON basket_item(transaction_id);

-- Subtype: something sold. MERCHANDISE = physical goods/dishes (stock-tracked);
-- NON_MERCHANDISE = service charge, delivery fee, tip, deposit, gift card, ad-hoc charge.
CREATE TABLE sale_item (
    basket_item_id    uuid PRIMARY KEY,
    kind              text NOT NULL DEFAULT 'SALE' CHECK (kind = 'SALE'),
    item_class        text NOT NULL CHECK (item_class IN ('MERCHANDISE','NON_MERCHANDISE')),
    non_merch_type    text CHECK (non_merch_type IN ('SERVICE_CHARGE','DELIVERY','TIP','DEPOSIT','GIFT_CARD','OTHER')),
    product_id        uuid REFERENCES product(id),               -- NULL for ad-hoc non-merchandise
    item_name         text    NOT NULL,                          -- snapshots: history survives catalog edits
    unit_price_minor  bigint  NOT NULL CHECK (unit_price_minor >= 0),
    quantity          numeric(12,3) NOT NULL CHECK (quantity > 0),
    discount_minor    bigint  NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
    tax_rate_bp       int     NOT NULL DEFAULT 0,
    tax_inclusive     boolean NOT NULL DEFAULT true,
    tax_minor         bigint  NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
    kitchen_sent_at   timestamptz,
    note              text,
    FOREIGN KEY (basket_item_id, kind) REFERENCES basket_item(id, kind) ON DELETE CASCADE,
    CHECK ((item_class = 'NON_MERCHANDISE') = (non_merch_type IS NOT NULL)),
    CHECK (item_class = 'NON_MERCHANDISE' OR product_id IS NOT NULL)
);
CREATE INDEX ix_sale_item_product ON sale_item(product_id);

-- Subtype: money received. basket_item.amount_minor = amount applied to the bill.
CREATE TABLE tender_item (
    basket_item_id  uuid PRIMARY KEY,
    kind            text NOT NULL DEFAULT 'TENDER' CHECK (kind = 'TENDER'),
    method          text NOT NULL CHECK (method IN ('CASH','CARD','OTHER')),
    tendered_minor  bigint CHECK (tendered_minor >= 0),          -- cash handed over
    change_minor    bigint CHECK (change_minor >= 0),
    reference       text,                                        -- card slip / note
    FOREIGN KEY (basket_item_id, kind) REFERENCES basket_item(id, kind) ON DELETE CASCADE
);

-- Modifiers belong to sale items only.
CREATE TABLE sale_item_modifier (
    id                 uuid PRIMARY KEY,
    sale_item_id       uuid   NOT NULL REFERENCES sale_item(basket_item_id) ON DELETE CASCADE,
    modifier_id        uuid   REFERENCES modifier(id),
    name               text   NOT NULL,
    price_delta_minor  bigint NOT NULL DEFAULT 0
);
CREATE INDEX ix_sim_item ON sale_item_modifier(sale_item_id);

-- Signed views: REFUND transactions count negative, so SUM() just works in reports and day-end.
CREATE VIEW v_sale_item_signed AS
    SELECT t.id AS transaction_id, t.business_date, t.cash_session_id, t.type,
           bi.id AS basket_item_id, si.item_class, si.non_merch_type, si.product_id, si.item_name,
           CASE WHEN t.type = 'REFUND' THEN -si.quantity ELSE si.quantity END AS quantity,
           CASE WHEN t.type = 'REFUND' THEN -bi.amount_minor ELSE bi.amount_minor END AS amount_minor,
           CASE WHEN t.type = 'REFUND' THEN -si.tax_minor ELSE si.tax_minor END AS tax_minor
    FROM pos_transaction t
    JOIN basket_item bi ON bi.transaction_id = t.id
    JOIN sale_item si ON si.basket_item_id = bi.id
    WHERE t.status = 'COMPLETED';

CREATE VIEW v_tender_signed AS
    SELECT t.id AS transaction_id, t.business_date, t.cash_session_id, t.type,
           bi.id AS basket_item_id, ti.method,
           CASE WHEN t.type = 'REFUND' THEN -bi.amount_minor ELSE bi.amount_minor END AS amount_minor
    FROM pos_transaction t
    JOIN basket_item bi ON bi.transaction_id = t.id
    JOIN tender_item ti ON ti.basket_item_id = bi.id
    WHERE t.status = 'COMPLETED';

-- ============ Stock ledger ============
CREATE TABLE stock_movement (
    id               uuid PRIMARY KEY,
    stock_item_id    uuid   NOT NULL REFERENCES stock_item(id),
    type             text   NOT NULL CHECK (type IN ('OPENING','PURCHASE','SALE','SALE_REVERSAL','ADJUSTMENT','WASTE')),
    quantity_delta   numeric(12,3) NOT NULL CHECK (quantity_delta <> 0),
    reason           text,
    sale_item_id     uuid   REFERENCES sale_item(basket_item_id),
    user_id          uuid   NOT NULL REFERENCES app_user(id),
    business_date    date   NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    CHECK (type NOT IN ('ADJUSTMENT','WASTE') OR reason IS NOT NULL)
);
CREATE INDEX ix_stock_movement_item ON stock_movement(stock_item_id, created_at);

CREATE VIEW stock_on_hand AS
    SELECT s.id AS stock_item_id, s.name, s.unit, s.reorder_level,
           COALESCE(SUM(m.quantity_delta), 0) AS quantity,
           COALESCE(SUM(m.quantity_delta), 0) <= s.reorder_level AS low_stock
    FROM stock_item s LEFT JOIN stock_movement m ON m.stock_item_id = s.id
    WHERE s.active
    GROUP BY s.id;

-- ============ Printing & audit ============
CREATE TABLE print_job (
    id          uuid PRIMARY KEY,
    type        text NOT NULL CHECK (type IN ('RECEIPT','REPRINT','KITCHEN','Z_REPORT','CASH_SLIP')),
    ref_id      uuid,                                  -- order / session / movement id
    payload     bytea,
    status      text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PRINTED','FAILED')),
    attempts    int  NOT NULL DEFAULT 0,
    last_error  text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    printed_at  timestamptz
);
CREATE INDEX ix_print_job_pending ON print_job(created_at) WHERE status <> 'PRINTED';

CREATE TABLE audit_log (
    id          uuid PRIMARY KEY,
    user_id     uuid REFERENCES app_user(id),
    action      text NOT NULL,                         -- ORDER_VOID, DISCOUNT, STOCK_ADJUST, DRAWER_OPEN, LOGIN_FAIL ...
    entity      text,
    entity_id   uuid,
    details     jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_created ON audit_log(created_at);

-- ============ Append-only enforcement ============
CREATE FUNCTION forbid_update_delete() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION '% is append-only (% not allowed)', TG_TABLE_NAME, TG_OP;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_stock_movement_append_only BEFORE UPDATE OR DELETE ON stock_movement
    FOR EACH ROW EXECUTE FUNCTION forbid_update_delete();
CREATE TRIGGER trg_cash_movement_append_only  BEFORE UPDATE OR DELETE ON cash_movement
    FOR EACH ROW EXECUTE FUNCTION forbid_update_delete();
CREATE TRIGGER trg_audit_append_only          BEFORE UPDATE OR DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION forbid_update_delete();

-- Closed day is locked: no new/changed transactions or cash movements against a CLOSED session.
CREATE FUNCTION require_open_session() RETURNS trigger AS $$
BEGIN
    IF (SELECT status FROM cash_session WHERE id = NEW.cash_session_id) <> 'OPEN' THEN
        RAISE EXCEPTION 'cash session % is closed', NEW.cash_session_id;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_txn_open_session      BEFORE INSERT OR UPDATE ON pos_transaction
    FOR EACH ROW EXECUTE FUNCTION require_open_session();
CREATE TRIGGER trg_cashmov_open_session  BEFORE INSERT ON cash_movement
    FOR EACH ROW EXECUTE FUNCTION require_open_session();

-- A transaction is immutable once COMPLETED or CANCELLED (OPEN -> COMPLETED/CANCELLED is the only move).
CREATE FUNCTION guard_transaction() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'transactions cannot be deleted; cancel instead';
    END IF;
    IF OLD.status <> 'OPEN' THEN
        RAISE EXCEPTION 'transaction % is % and immutable', OLD.id, OLD.status;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_txn_guard BEFORE UPDATE OR DELETE ON pos_transaction
    FOR EACH ROW EXECUTE FUNCTION guard_transaction();

-- Items, tenders and modifiers can change only while their transaction is OPEN.
CREATE FUNCTION require_open_transaction() RETURNS trigger AS $$
DECLARE j jsonb; st text;
BEGIN
    IF TG_OP = 'DELETE' THEN j := to_jsonb(OLD); ELSE j := to_jsonb(NEW); END IF;
    st := CASE TG_TABLE_NAME
        WHEN 'basket_item' THEN
            (SELECT t.status FROM pos_transaction t WHERE t.id = (j->>'transaction_id')::uuid)
        WHEN 'sale_item' THEN
            (SELECT t.status FROM basket_item bi JOIN pos_transaction t ON t.id = bi.transaction_id
              WHERE bi.id = (j->>'basket_item_id')::uuid)
        WHEN 'tender_item' THEN
            (SELECT t.status FROM basket_item bi JOIN pos_transaction t ON t.id = bi.transaction_id
              WHERE bi.id = (j->>'basket_item_id')::uuid)
        WHEN 'sale_item_modifier' THEN
            (SELECT t.status FROM basket_item bi JOIN pos_transaction t ON t.id = bi.transaction_id
              WHERE bi.id = (j->>'sale_item_id')::uuid)
    END;
    IF st IS NOT NULL AND st <> 'OPEN' THEN
        RAISE EXCEPTION '% change rejected: transaction is %', TG_TABLE_NAME, st;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_bitem_open    BEFORE INSERT OR UPDATE OR DELETE ON basket_item
    FOR EACH ROW EXECUTE FUNCTION require_open_transaction();
CREATE TRIGGER trg_sitem_open    BEFORE INSERT OR UPDATE OR DELETE ON sale_item
    FOR EACH ROW EXECUTE FUNCTION require_open_transaction();
CREATE TRIGGER trg_titem_open    BEFORE INSERT OR UPDATE OR DELETE ON tender_item
    FOR EACH ROW EXECUTE FUNCTION require_open_transaction();
CREATE TRIGGER trg_sim_open      BEFORE INSERT OR UPDATE OR DELETE ON sale_item_modifier
    FOR EACH ROW EXECUTE FUNCTION require_open_transaction();
